import {useEffect,useRef,useState,type FormEvent} from 'react';
import {ComposedChart,Area,Line,PieChart,Pie,Cell,ResponsiveContainer,Tooltip,XAxis,YAxis,CartesianGrid,Legend} from 'recharts';
import {
  WalletCards,LayoutDashboard,ReceiptText,Landmark,Settings,Users,Plus,Search,Sparkles,LogOut,SunMoon,
  ShieldCheck,CalendarClock,TrendingDown,Trash2,Pencil,Menu,X,ChevronRight,CheckCircle2,Bell,EyeOff,RotateCcw,
  Server,BrainCircuit,Copy,Download,Upload,Languages,Database,MessageSquarePlus,Send,Target,ListFilter,LoaderCircle,BookOpen,ChevronDown,KeyRound
} from 'lucide-react';
import Modal from './components/Modal';
import ExpenseForm from './components/ExpenseForm';
import {useI18n,localeFor,type Language} from './i18n';
import {
  api,money,dateFmt,type Expense,type Account,type Category,type User,type RemindersResponse,type ReminderItem,
  type AIProvider,type AIProfile,type UserPreferences,type AIConversation,type AIBrain
} from './lib/api';

type View='dashboard'|'costs'|'accounts'|'ai'|'users'|'settings';
const themeNames=['system','light','midnight','nordic','graphite','emerald'];
const isoDate=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateAtNoon=(value:string)=>new Date(value+'T12:00:00');
const addMonthsDate=(d:Date,months:number)=>{const day=d.getDate();const n=new Date(d.getFullYear(),d.getMonth()+months,1,12);n.setDate(Math.min(day,new Date(n.getFullYear(),n.getMonth()+1,0).getDate()));return n};
const priceAt=(x:Expense,d:Date)=>{const key=isoDate(d);const phases=[...(x.price_history||[])].sort((a,b)=>a.valid_from.localeCompare(b.valid_from));const found=phases.filter(p=>p.valid_from<=key).at(-1);return found?.amount??phases[0]?.amount??x.amount};
const firstKnownDate=(x:Expense)=>{const candidates=[x.start_date,...(x.price_history||[]).map(p=>p.valid_from)].filter(Boolean) as string[];return candidates.sort()[0]||null};
const projectedContractEnd=(x:Expense,d:Date)=>{const raw=[x.contract_end,x.effective_contract_end].filter(Boolean).sort().at(-1) as string|undefined;if(!raw)return null;let end=dateAtNoon(raw);if(x.auto_renew&&x.status==='active'&&x.renewal_period_months){let guard=0;while(end<d&&guard<600){end=addMonthsDate(end,x.renewal_period_months);guard++}}return end};
const inContractMonth=(x:Expense,year:number,month:number)=>{const first=new Date(year,month,1,12);const last=new Date(year,month+1,0,12);const start=firstKnownDate(x);if(start&&dateAtNoon(start)>last)return false;const currentYear=new Date().getFullYear();if(year>=currentYear&&['paused','ended'].includes(x.status))return false;const end=projectedContractEnd(x,last);return !end||end>=first};
const activeNow=(x:Expense)=>{const now=new Date();const start=firstKnownDate(x);if(start&&isoDate(now)<start)return false;if(['paused','ended'].includes(x.status))return false;const end=projectedContractEnd(x,now);return !end||end>=now};
const relevantInYear=(x:Expense,year:number)=>{const currentYear=new Date().getFullYear();if(year===currentYear)return activeNow(x);return Array.from({length:12},(_,i)=>i).some(i=>inContractMonth(x,year,i))};
const normalizedAt=(x:Expense,d:Date)=>{if(x.recurrence_type==='one_time'){const due=x.next_due_date||x.start_date;return due&&due.slice(0,7)===isoDate(d).slice(0,7)?priceAt(x,d):0}const raw=x.contract_end?dateAtNoon(x.contract_end):null;const amount=(x.auto_renew&&x.renewal_amount&&raw&&d>raw)?x.renewal_amount:priceAt(x,d);return amount/Math.max(1,x.interval_months||1)};
const projectedEndInYear=(x:Expense,year:number)=>{const raw=[x.contract_end,x.effective_contract_end].filter(Boolean).sort().at(-1) as string|undefined;if(!raw)return null;let end=dateAtNoon(raw);if(x.auto_renew&&x.status==='active'&&x.renewal_period_months){let guard=0;while(end.getFullYear()<year&&guard<600){end=addMonthsDate(end,x.renewal_period_months);guard++}}return end.getFullYear()===year?end:null};
const cloneDraftFrom=(x:Expense):Expense=>({...x,id:0,name:'',provider:'',amount:0,monthly_equivalent:0,yearly_equivalent:0,start_date:null,next_due_date:null,contract_end:null,effective_contract_end:null,cancellation_date:null,effective_cancellation_date:null,minimum_term_months:null,renewal_period_months:null,renewal_amount:null,cancellation_notice_days:null,cancelled_on:null,auto_renew:false,contract_url:'',contract_reference:'',status:'active',essential:false,tags:'',notes:'',price_history:[],next_price_change:null});

function Login({bootstrap,onDone}:{bootstrap:boolean;onDone:()=>void}){
  const{t}=useI18n();
  const[username,setUsername]=useState('admin');const[name,setName]=useState('Administrator');const[password,setPassword]=useState('');const[error,setError]=useState('');const[busy,setBusy]=useState(false);
  return <main className="auth-shell"><section className="auth-card"><div className="brand-mark big">P</div><h1>PenguCost</h1><p>{bootstrap?t('login.setup'):t('login.signin')}</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await api(bootstrap?'/api/auth/bootstrap':'/api/auth/login',{method:'POST',body:JSON.stringify(bootstrap?{username,display_name:name,password}:{username,password})});onDone()}catch(x:any){setError(x.message)}finally{setBusy(false)}}}><label>{t('login.username')}<input value={username} onChange={e=>setUsername(e.target.value)} autoFocus/></label>{bootstrap&&<label>{t('login.display')}<input value={name} onChange={e=>setName(e.target.value)}/></label>}<label>{t('login.password')}<input type="password" value={password} minLength={8} onChange={e=>setPassword(e.target.value)}/></label>{error&&<div className="error">{error}</div>}<button className="wide">{busy?t('login.wait'):bootstrap?t('login.bootstrap'):t('login.submit')}</button></form><small>{t('login.local')}</small></section></main>
}

export default function App(){
  const{t,language,setLanguage}=useI18n();
  const currentYear=new Date().getFullYear();
  const[auth,setAuth]=useState<'loading'|'bootstrap'|'login'|'ready'>('loading');
  const[me,setMe]=useState<User|null>(null);const[view,setView]=useState<View>('dashboard');
  const[expenses,setExpenses]=useState<Expense[]>([]);const[accounts,setAccounts]=useState<Account[]>([]);const[categories,setCategories]=useState<Category[]>([]);
  const[reminders,setReminders]=useState<RemindersResponse>({count:0,reminder_days:30,items:[]});const[reminderOpen,setReminderOpen]=useState(false);
  const[selected,setSelected]=useState<Set<number>>(new Set());const[dashboardYear,setDashboardYear]=useState(currentYear);
  const[editing,setEditing]=useState<Expense|null|undefined>(undefined);const[cloneDraft,setCloneDraft]=useState(false);const[mobile,setMobile]=useState(false);const[query,setQuery]=useState('');
  const[theme,setTheme]=useState(localStorage.getItem('pengucost-theme')||'system');const[aiRunning,setAiRunning]=useState(0);

  const refreshReminders=async()=>{try{setReminders(await api<RemindersResponse>('/api/reminders'))}catch{}};
  const changeTheme=(next:string)=>{setTheme(next);if(auth==='ready')api('/api/settings/preferences',{method:'PUT',body:JSON.stringify({theme:next})}).catch(()=>{})};
  const refresh=async()=>{
    const[u,e,a,c,r,p]=await Promise.all([api<User>('/api/me'),api<Expense[]>('/api/expenses'),api<Account[]>('/api/accounts'),api<Category[]>('/api/categories'),api<RemindersResponse>('/api/reminders'),api<UserPreferences>('/api/settings/preferences')]);
    setMe(u);setExpenses(e);setAccounts(a);setCategories(c);setReminders(r);setLanguage(p.language);setTheme(p.theme||'system');
  };
  const boot=async()=>{try{const s=await api<{needs_bootstrap:boolean}>('/api/auth/status');if(s.needs_bootstrap){setAuth('bootstrap');return}try{await refresh();setAuth('ready')}catch{setAuth('login')}}catch{setAuth('login')}};
  useEffect(()=>{boot()},[]);
  useEffect(()=>{localStorage.setItem('pengucost-theme',theme);const actual=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'midnight':'light'):theme;document.documentElement.dataset.theme=actual},[theme]);
  useEffect(()=>{if(auth!=='ready')return;const poll=()=>api<AIConversation[]>('/api/ai/conversations').then(x=>setAiRunning(x.filter(c=>c.status==='running').length)).catch(()=>{});poll();const timer=setInterval(poll,5000);return()=>clearInterval(timer)},[auth]);

  const historicalYears=(()=>{if(!expenses.length)return[] as number[];const known=expenses.flatMap(x=>[firstKnownDate(x),x.contract_end].filter(Boolean).map(v=>Number(String(v).slice(0,4)))).filter(y=>Number.isFinite(y));const earliest=Math.max(currentYear-30,Math.min(currentYear,...known));const years:number[]=[];for(let y=currentYear-1;y>=earliest;y--)if(expenses.some(x=>relevantInYear(x,y)))years.push(y);return years})();
  const periodRows=dashboardYear===currentYear?expenses.filter(activeNow):expenses.filter(x=>relevantInYear(x,dashboardYear));
  useEffect(()=>{setSelected(new Set(periodRows.map(x=>x.id)))},[dashboardYear,expenses]);

  if(auth==='loading')return <div className="splash"><div className="brand-mark big">P</div></div>;
  if(auth==='bootstrap'||auth==='login')return <Login bootstrap={auth==='bootstrap'} onDone={async()=>{setSelected(new Set());setDashboardYear(currentYear);await refresh();setAuth('ready')}}/>;

  const active=expenses.filter(activeNow);const selectedRows=periodRows.filter(x=>selected.has(x.id));
  const expenseRows=selectedRows.filter(x=>x.entry_type!=='income');const incomeRows=selectedRows.filter(x=>x.entry_type==='income');
  const monthSeries=Array.from({length:12},(_,i)=>{const d=new Date(dashboardYear,i,15,12);let expense=0,income=0;for(const x of selectedRows){if(!inContractMonth(x,dashboardYear,i))continue;const value=normalizedAt(x,d);if(x.entry_type==='income')income+=value;else expense+=value}return{name:new Intl.DateTimeFormat(localeFor(language),{month:'short'}).format(new Date(dashboardYear,i,1)),expense:Number(expense.toFixed(2)),income:Number(income.toFixed(2)),delta:Number((income-expense).toFixed(2))}});
  const periodExpenseYear=monthSeries.reduce((s,x)=>s+x.expense,0);const periodIncomeYear=monthSeries.reduce((s,x)=>s+x.income,0);
  const monthlyExpenses=dashboardYear===currentYear?expenseRows.reduce((s,x)=>s+x.monthly_equivalent,0):periodExpenseYear/12;
  const yearlyExpenses=dashboardYear===currentYear?expenseRows.reduce((s,x)=>s+x.yearly_equivalent,0):periodExpenseYear;
  const monthlyIncome=dashboardYear===currentYear?incomeRows.reduce((s,x)=>s+x.monthly_equivalent,0):periodIncomeYear/12;
  const yearlyIncome=dashboardYear===currentYear?incomeRows.reduce((s,x)=>s+x.yearly_equivalent,0):periodIncomeYear;
  const monthlyDelta=monthlyIncome-monthlyExpenses;
  const prevYear=dashboardYear-1;const prevRows=expenses.filter(x=>relevantInYear(x,prevYear));const prevSeries=Array.from({length:12},(_,i)=>{const d=new Date(prevYear,i,15,12);let expense=0,income=0;for(const x of prevRows){if(!inContractMonth(x,prevYear,i))continue;const v=normalizedAt(x,d);x.entry_type==='income'?income+=v:expense+=v}return{expense,income}});const prevExpenseYear=prevSeries.reduce((s,x)=>s+x.expense,0);const prevIncomeYear=prevSeries.reduce((s,x)=>s+x.income,0);const comparison={year:prevYear,expenses:prevExpenseYear,income:prevIncomeYear,delta:prevIncomeYear-prevExpenseYear,has:prevRows.length>0};
  const averageForEntry=(x:Expense)=>dashboardYear===currentYear?x.monthly_equivalent:Array.from({length:12},(_,i)=>{const d=new Date(dashboardYear,i,15,12);return inContractMonth(x,dashboardYear,i)?normalizedAt(x,d):0}).reduce((a,b)=>a+b,0)/12;
  const categoryData=(rows:Expense[])=>Object.values(rows.reduce((m:any,x)=>{const name=x.category||t('costs.noCategory');if(!m[name])m[name]={name,value:0,color:x.category_color||'#7B8798'};m[name].value+=averageForEntry(x);return m},{})).map((x:any)=>({...x,value:Number(x.value.toFixed(2))})).filter((x:any)=>x.value>0).sort((a:any,b:any)=>b.value-a.value);
  const expenseCats=categoryData(expenseRows);const incomeCats=categoryData(incomeRows);
  const contractRows=periodRows.filter(x=>x.entry_type!=='income');
  const expiring=dashboardYear===currentYear?contractRows.filter(x=>{const d=x.effective_contract_end||x.contract_end;return d&&dateAtNoon(d)<=new Date(Date.now()+60*86400000)&&dateAtNoon(d)>=new Date()}):contractRows.flatMap(x=>{const d=projectedEndInYear(x,dashboardYear);return d?[{...x,effective_contract_end:isoDate(d)}]:[]});
  const cancelDue=dashboardYear===currentYear?contractRows.filter(x=>{const d=x.effective_cancellation_date||x.cancellation_date;return d&&dateAtNoon(d)<=new Date(Date.now()+60*86400000)&&dateAtNoon(d)>=new Date()}):contractRows.flatMap(x=>{const end=projectedEndInYear(x,dashboardYear);if(!end||x.cancellation_notice_days==null)return[];const d=new Date(end);d.setDate(d.getDate()-Math.max(0,x.cancellation_notice_days));return d.getFullYear()===dashboardYear?[{...x,effective_cancellation_date:isoDate(d)}]:[]});
  const nav=[['dashboard',t('nav.dashboard'),LayoutDashboard],['costs',t('nav.costs'),ReceiptText],['accounts',t('nav.accounts'),Landmark],['ai',t('nav.ai'),Sparkles],...(me?.role==='admin'?[['users',t('nav.users'),Users] as any]:[]),['settings',t('nav.settings'),Settings]] as [View,string,any][];

  return <div className="app-shell">
    <aside className={mobile?'sidebar open':'sidebar'}><div className="brand"><div className="brand-mark">P</div><div><strong>PenguCost</strong><span>{t('brand.tagline')}</span></div><button className="icon-btn mobile-close" onClick={()=>setMobile(false)}><X size={18}/></button></div><nav>{nav.map(([id,label,Icon])=><button key={id} className={view===id?'active':''} onClick={()=>{setView(id);setMobile(false)}}><Icon size={18}/><span>{label}</span>{id==='ai'&&aiRunning>0&&<span className="nav-badge pulse">{aiRunning}</span>}</button>)}</nav><div className="sidebar-footer"><div className="user-chip"><div className="avatar">{(me?.display_name||me?.username||'?')[0].toUpperCase()}</div><div><strong>{me?.display_name||me?.username}</strong><span>{me?.role==='admin'?t('role.admin'):t('role.user')}</span><small>{t('version',{version:me?.version||'0.4.2'})}</small></div></div><button className="icon-btn" title={t('logout')} onClick={async()=>{await api('/api/auth/logout',{method:'POST'});setSelected(new Set());setExpenses([]);setAuth('login')}}><LogOut size={18}/></button></div></aside>
    <section className="main"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobile(true)}><Menu size={19}/></button><div className="page-title"><span>PenguCost</span><strong>{nav.find(n=>n[0]===view)?.[1]}</strong></div><div className="top-actions"><button className="ghost compact" onClick={()=>setEditing(null)}><Plus size={17}/>{t('add.entry')}</button><button className="icon-btn bell-btn" title={t('reminders.title',{count:reminders.count})} onClick={()=>setReminderOpen(true)}><Bell size={19}/>{reminders.count>0&&<span className="bell-badge">{reminders.count>99?'99+':reminders.count}</span>}</button><select className="theme-select" value={theme} onChange={e=>changeTheme(e.target.value)} aria-label="Theme"><option value="system">System</option><option value="light">Light</option><option value="midnight">Midnight</option><option value="nordic">Nordic</option><option value="graphite">Graphite</option><option value="emerald">Emerald</option></select>{aiRunning>0&&<button className="icon-btn ai-global-status" title={t('ai.backgroundHint')} onClick={()=>setView('ai')}><LoaderCircle className="spin" size={18}/><span>{aiRunning}</span></button>}<SunMoon size={18}/></div></header>
      <div className="content">
        {view==='dashboard'&&<Dashboard expenses={periodRows} selected={selected} setSelected={setSelected} monthlyExpenses={monthlyExpenses} yearlyExpenses={yearlyExpenses} monthlyIncome={monthlyIncome} yearlyIncome={yearlyIncome} monthlyDelta={monthlyDelta} expenseCats={expenseCats} incomeCats={incomeCats} monthSeries={monthSeries} expiring={expiring} cancelDue={cancelDue} onOpen={()=>setEditing(null)} dashboardYear={dashboardYear} currentYear={currentYear} historicalYears={historicalYears} onYearChange={setDashboardYear} averageForEntry={averageForEntry} comparison={comparison}/>}
        {view==='costs'&&<Costs expenses={expenses} accounts={accounts} categories={categories} refresh={refresh} query={query} setQuery={setQuery} onAdd={()=>{setCloneDraft(false);setEditing(null)}} onEdit={x=>{setCloneDraft(false);setEditing(x)}} onClone={x=>{setCloneDraft(true);setEditing(cloneDraftFrom(x))}} onDelete={async x=>{if(confirm(t('confirm.delete',{name:x.name}))){await api(`/api/expenses/${x.id}`,{method:'DELETE'});await refresh()}}}/>}
        {view==='accounts'&&<Accounts accounts={accounts} categories={categories} refresh={refresh} isAdmin={me?.role==='admin'}/>}
        {view==='ai'&&<AIPage expenses={active} isAdmin={me?.role==='admin'}/>}
        {view==='users'&&me?.role==='admin'&&<UsersPage/>}
        {view==='settings'&&<SettingsPage theme={theme} setTheme={changeTheme} categories={categories} refresh={refresh} refreshReminders={refreshReminders} isAdmin={me?.role==='admin'} language={language} setLanguage={setLanguage}/>}
      </div>
    </section>
    {reminderOpen&&<Modal title={t('reminders.title',{count:reminders.count})} onClose={()=>setReminderOpen(false)}><ReminderCenter reminders={reminders} onEdit={x=>{const item=expenses.find(e=>e.id===x.expense_id);setReminderOpen(false);if(item)setEditing(item)}} onChanged={refresh}/></Modal>}
    {editing!==undefined&&<Modal title={cloneDraft?t('clone.entry'):editing?t('edit.entry'):t('new.entry')} onClose={()=>{setEditing(undefined);setCloneDraft(false)}}><ExpenseForm expense={editing||undefined} isClone={cloneDraft} accounts={accounts} categories={categories} existingExpenses={expenses} onCategoryAdded={refresh} onCancel={()=>{setEditing(undefined);setCloneDraft(false)}} onSave={async data=>{if(editing&&!cloneDraft)await api(`/api/expenses/${editing.id}`,{method:'PUT',body:JSON.stringify(data)});else await api('/api/expenses',{method:'POST',body:JSON.stringify(data)});setEditing(undefined);setCloneDraft(false);await refresh()}}/></Modal>}
  </div>
}

function Stat({label,value,sub,icon:Icon}:{label:string;value:string;sub:string;icon:any}){return <article className="stat card"><div className="stat-icon"><Icon size={19}/></div><div><span>{label}</span><strong>{value}</strong><small>{sub}</small></div></article>}

function YearPicker({value,currentYear,historicalYears,onChange}:{value:number;currentYear:number;historicalYears:number[];onChange:(year:number)=>void}){
  const[open,setOpen]=useState(false);const ref=useRef<HTMLDivElement>(null);
  const years=Array.from(new Set([...historicalYears,currentYear,currentYear+1,currentYear+2,currentYear+5])).sort((a,b)=>a-b);
  useEffect(()=>{const fn=(e:MouseEvent)=>{if(ref.current&&!ref.current.contains(e.target as Node))setOpen(false)};document.addEventListener('mousedown',fn);return()=>document.removeEventListener('mousedown',fn)},[]);
  return <div className="year-picker" ref={ref}><button type="button" className="year-picker-trigger" onClick={()=>setOpen(v=>!v)}><CalendarClock size={18}/><span>{value}</span><ChevronDown size={15}/></button>{open&&<div className="year-picker-menu">{years.map(y=><button type="button" key={y} className={y===value?'active':''} onClick={()=>{onChange(y);setOpen(false)}}>{y}</button>)}</div>}</div>
}

function Dashboard({expenses,selected,setSelected,monthlyExpenses,yearlyExpenses,monthlyIncome,yearlyIncome,monthlyDelta,expenseCats,incomeCats,monthSeries,expiring,cancelDue,onOpen,dashboardYear,currentYear,historicalYears,onYearChange,averageForEntry,comparison}:{expenses:Expense[];selected:Set<number>;setSelected:(s:Set<number>)=>void;monthlyExpenses:number;yearlyExpenses:number;monthlyIncome:number;yearlyIncome:number;monthlyDelta:number;expenseCats:any[];incomeCats:any[];monthSeries:any[];expiring:Expense[];cancelDue:Expense[];onOpen:()=>void;dashboardYear:number;currentYear:number;historicalYears:number[];onYearChange:(year:number)=>void;averageForEntry:(x:Expense)=>number;comparison:{year:number;expenses:number;income:number;delta:number;has:boolean}}){
  const{t,language}=useI18n();const toggle=(id:number)=>{const n=new Set(selected);n.has(id)?n.delete(id):n.add(id);setSelected(n)};
  const out=expenses.filter(x=>x.entry_type!=='income');const inc=expenses.filter(x=>x.entry_type==='income');const selectedOut=out.filter(x=>selected.has(x.id));const selectedInc=inc.filter(x=>selected.has(x.id));const isCurrent=dashboardYear===currentYear;const isForecast=dashboardYear>currentYear;
  const periodLabel=String(dashboardYear);
  const donut=(data:any[],total:number,title:string)=><article className="card chart-card compact-chart"><div className="card-head"><div><h2>{title}</h2><p>{t('chart.monthShare')}</p></div></div><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey="value" innerRadius={62} outerRadius={88} paddingAngle={3}>{data.map((c:any,i:number)=><Cell key={i} fill={c.color||`var(--chart-${i%6})`}/>)}</Pie><Tooltip formatter={(v:any)=>money(Number(v))} contentStyle={{background:'var(--panel)',border:'1px solid var(--line)',borderRadius:12}}/></PieChart></ResponsiveContainer><div className="donut-center"><strong>{money(total)}</strong><span>{t('perMonth')}</span></div></div><div className="legend">{data.slice(0,5).map((c:any,i:number)=><div key={c.name}><i style={{background:c.color||`var(--chart-${i%6})`}}></i><span>{c.name}</span><b>{money(c.value)}</b></div>)}{!data.length&&<div className="empty small">{t('chart.noData')}</div>}</div></article>;
  return <>
    <div className="hero"><div><span className="eyebrow">{t('dashboard.eyebrow')}</span><h1>{t('dashboard.hero1')}<br/><em>{t('dashboard.hero2')}</em></h1><p>{t('dashboard.heroSub')}</p></div><div className="hero-actions"><YearPicker value={dashboardYear} currentYear={currentYear} historicalYears={historicalYears} onChange={onYearChange}/><button onClick={onOpen}><Plus size={18}/>{t('new.entry')}</button></div></div>
    <div className="period-summary"><strong>{periodLabel}</strong><span>{isCurrent?t('dashboard.periodCurrentHelp'):isForecast?t('dashboard.periodForecastHelp'):t('dashboard.periodHistoryHelp')}</span>{comparison.has&&<span className="year-compare">{t('dashboard.comparePrev',{year:comparison.year,value:money(yearlyExpenses-comparison.expenses)})}</span>}{isForecast&&<details className="forecast-explain"><summary>?</summary><div>{t('dashboard.forecastExplain')}<ul>{expenses.filter(x=>x.auto_renew||x.next_price_change||x.renewal_amount).slice(0,8).map(x=><li key={x.id}><b>{x.name}</b>{x.renewal_amount?` · ${t('form.renewAmount')}: ${money(x.renewal_amount)}`:''}{x.effective_contract_end?` · ${t('dates.contractEnd')}: ${dateFmt(x.effective_contract_end)}`:''}</li>)}</ul></div></details>}</div>
    <div className="stats-grid"><Stat label={isCurrent?t('stat.expenses'):t('stat.avgExpenses')} value={money(monthlyExpenses)} sub={t('stat.yearValue',{value:money(yearlyExpenses)})} icon={WalletCards}/><Stat label={isCurrent?t('stat.income'):t('stat.avgIncome')} value={money(monthlyIncome)} sub={t('stat.yearValue',{value:money(yearlyIncome)})} icon={Landmark}/><Stat label={isCurrent?t('stat.delta'):t('stat.avgDelta')} value={money(monthlyDelta)} sub={monthlyDelta>=0?t('stat.surplus'):t('stat.deficit')} icon={TrendingDown}/><Stat label={t('stat.contracts')} value={String(out.length)} sub={t('stat.autoRenew',{count:out.filter(x=>x.auto_renew).length})} icon={ShieldCheck}/></div>
    <article className="card chart-card cashflow-chart"><div className="card-head"><div><h2>{t('chart.cashflow')}</h2><p>{t('chart.cashflowYear',{year:dashboardYear})}</p></div><span className={`metric ${monthlyDelta<0?'negative':'positive'}`}>{t('stat.delta')}: {money(monthlyDelta)}</span></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={monthSeries}><defs><linearGradient id="fillExpense" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--danger)" stopOpacity={.20}/><stop offset="100%" stopColor="var(--danger)" stopOpacity={0}/></linearGradient><linearGradient id="fillIncome" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--chart-5)" stopOpacity={.20}/><stop offset="100%" stopColor="var(--chart-5)" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--line)"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:12}}/><YAxis hide/><Tooltip contentStyle={{background:'var(--panel)',border:'1px solid var(--line)',borderRadius:12}} formatter={(v:any)=>money(Number(v))}/><Legend/><Area type="monotone" name={t('type.expenses')} dataKey="expense" stroke="var(--danger)" strokeWidth={2.2} fill="url(#fillExpense)"/><Area type="monotone" name={t('type.incomes')} dataKey="income" stroke="var(--chart-5)" strokeWidth={2.2} fill="url(#fillIncome)"/><Line type="monotone" name={t('stat.delta')} dataKey="delta" stroke="var(--accent)" strokeWidth={2} strokeDasharray="5 4" dot={false}/></ComposedChart></ResponsiveContainer></div></article>
    <div className="dashboard-grid category-panels">{donut(expenseCats,monthlyExpenses,t('chart.expenseCategory'))}{donut(incomeCats,monthlyIncome,t('chart.incomeCategory'))}</div>
    <div className="dashboard-grid lower"><article className="card wide"><div className="card-head"><div><h2>{t('selection.title')}</h2><p>{t('selection.helpPeriod',{year:dashboardYear})}</p></div><button className="text-btn" onClick={()=>setSelected(new Set(selected.size===expenses.length?[]:expenses.map(x=>x.id)))}>{selected.size===expenses.length?t('selection.none'):t('selection.all')}</button></div>{out.length>0&&<><h3 className="selection-group-title">{t('type.expenses')} <span>{selectedOut.length}/{out.length}</span></h3><div className="filter-chips">{out.map(x=><button key={x.id} className={selected.has(x.id)?'cost-chip selected expense-chip':'cost-chip expense-chip'} onClick={()=>toggle(x.id)}><span className="check-dot">{selected.has(x.id)&&<CheckCircle2 size={14}/>}</span><span>{x.name}</span><b>{money(averageForEntry(x))}</b></button>)}</div></>}{inc.length>0&&<><h3 className="selection-group-title income-title">{t('type.incomes')} <span>{selectedInc.length}/{inc.length}</span></h3><div className="filter-chips">{inc.map(x=><button key={x.id} className={selected.has(x.id)?'cost-chip selected income-chip':'cost-chip income-chip'} onClick={()=>toggle(x.id)}><span className="check-dot">{selected.has(x.id)&&<CheckCircle2 size={14}/>}</span><span>{x.name}</span><b>{money(averageForEntry(x))}</b></button>)}</div></>}</article>
      <article className="card"><div className="card-head"><div><h2>{t('dates.title')}</h2><p>{isCurrent?t('dates.sub'):t('dates.subYear',{year:dashboardYear})}</p></div></div><div className="timeline">{[...cancelDue.map(x=>({...x,_type:t('dates.cancelBy'),_date:x.effective_cancellation_date||x.cancellation_date})),...expiring.map(x=>({...x,_type:t('dates.contractEnd'),_date:x.effective_contract_end||x.contract_end}))].sort((a:any,b:any)=>String(a._date).localeCompare(String(b._date))).slice(0,5).map((x:any)=><div className="timeline-row" key={`${x.id}-${x._type}-${x._date}`}><div className="datebox"><strong>{new Date(x._date+'T12:00:00').getDate()}</strong><span>{new Intl.DateTimeFormat(localeFor(language),{month:'short'}).format(new Date(x._date+'T12:00:00'))}</span></div><div><strong>{x.name}</strong><span>{x._type}</span></div><ChevronRight size={17}/></div>)}{!cancelDue.length&&!expiring.length&&<div className="empty small">{isCurrent?t('dates.empty'):t('dates.emptyYear',{year:dashboardYear})}</div>}</div></article></div>
  </>
}

function Costs({expenses,accounts,categories,query,setQuery,onAdd,onEdit,onClone,onDelete,refresh}:{expenses:Expense[];accounts:Account[];categories:Category[];query:string;setQuery:(v:string)=>void;onAdd:()=>void;onEdit:(x:Expense)=>void;onClone:(x:Expense)=>void;onDelete:(x:Expense)=>void;refresh:()=>Promise<void>}){
  const{t}=useI18n();const[typeFilter,setTypeFilter]=useState<'all'|'expense'|'income'>('all');
  const[sort,setSort]=useState<{key:string;dir:1|-1}>({key:'name',dir:1});const[selectedRows,setSelectedRows]=useState<Set<number>>(new Set());
  const[filter,setFilter]=useState<any>({accounts:[],categories:[],statuses:[],billing:[],tag:'',min:'',max:'',autoRenew:false,uncategorized:false});
  const defaultCols=['type','category','billing','month','year','account','status','cancel'];
  const[columns,setColumns]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('pengucost-cost-columns')||'null')||defaultCols}catch{return defaultCols}});
  const[savedViews,setSavedViews]=useState<Record<string,any>>(()=>{try{return JSON.parse(localStorage.getItem('pengucost-saved-views')||'{}')}catch{return{}}});
  const[viewName,setViewName]=useState('');const[bulkAction,setBulkAction]=useState('');const[bulkValue,setBulkValue]=useState('');
  useEffect(()=>localStorage.setItem('pengucost-cost-columns',JSON.stringify(columns)),[columns]);useEffect(()=>localStorage.setItem('pengucost-saved-views',JSON.stringify(savedViews)),[savedViews]);
  const interval=(x:Expense)=>x.recurrence_type==='one_time'?t('form.oneTime'):x.billing_interval==='custom'?t('interval.months',{count:x.interval_months}):t(`interval.${x.billing_interval}`);
  const filtered=expenses.filter(x=>{const q=query.toLowerCase();if(typeFilter!=='all'&&x.entry_type!==typeFilter)return false;if(!(x.name+' '+x.provider+' '+(x.category||'')+' '+(x.account||'')+' '+(x.tags||'')).toLowerCase().includes(q))return false;if(filter.accounts.length&&!filter.accounts.includes(String(x.account_id??'')))return false;if(filter.categories.length&&!filter.categories.includes(String(x.category_id??'')))return false;if(filter.statuses.length&&!filter.statuses.includes(x.status))return false;if(filter.billing.length&&!filter.billing.includes(x.billing_interval))return false;if(filter.tag&&!String(x.tags||'').toLowerCase().includes(filter.tag.toLowerCase()))return false;if(filter.min!==''&&x.monthly_equivalent<Number(filter.min))return false;if(filter.max!==''&&x.monthly_equivalent>Number(filter.max))return false;if(filter.autoRenew&&!x.auto_renew)return false;if(filter.uncategorized&&x.category_id!=null)return false;return true});
  const valueFor=(x:Expense,key:string):any=>({name:x.name,type:x.entry_type,category:x.category||'',billing:x.billing_interval,month:x.monthly_equivalent,year:x.yearly_equivalent,account:x.account||'',status:x.status,cancel:x.effective_cancellation_date||x.cancellation_date||''} as any)[key];
  const rows=[...filtered].sort((a,b)=>{const av=valueFor(a,sort.key),bv=valueFor(b,sort.key);return(av===bv?0:av>bv?1:-1)*sort.dir});
  const toggleSort=(key:string)=>setSort(p=>p.key===key?{key,dir:(p.dir*-1) as 1|-1}:{key,dir:1});
  const resetFilters=()=>{setFilter({accounts:[],categories:[],statuses:[],billing:[],tag:'',min:'',max:'',autoRenew:false,uncategorized:false});setTypeFilter('all');setQuery('')};
  const toggleArray=(key:string,value:string)=>setFilter((p:any)=>({...p,[key]:p[key].includes(value)?p[key].filter((v:string)=>v!==value):[...p[key],value]}));
  const header=(label:string,key:string,filterBody?:any)=><div className="th-inner"><button className="th-sort" onClick={()=>toggleSort(key)}>{label}<span>{sort.key===key?(sort.dir===1?'↑':'↓'):''}</span></button>{filterBody&&<details className="column-filter"><summary title={t('filter.filter')}><ListFilter size={13}/></summary><div className="filter-popover" onClick={e=>e.stopPropagation()}>{filterBody}</div></details>}</div>;
  const checkboxList=(key:string,items:{id:string;name:string}[])=> <div className="filter-checklist">{items.map(i=><label key={i.id}><input type="checkbox" checked={filter[key].includes(i.id)} onChange={()=>toggleArray(key,i.id)}/><span>{i.name}</span></label>)}</div>;
  const saveView=()=>{const name=viewName.trim()||`View ${Object.keys(savedViews).length+1}`;setSavedViews({...savedViews,[name]:{filter,typeFilter,query,columns,sort}});setViewName('')};
  const loadView=(name:string)=>{const v=savedViews[name];if(!v)return;setFilter(v.filter);setTypeFilter(v.typeFilter);setQuery(v.query);setColumns(v.columns||defaultCols);setSort(v.sort||{key:'name',dir:1})};
  const bulk=async()=>{if(!selectedRows.size||!bulkAction)return;if(bulkAction==='delete'&&!confirm(t('costs.bulkDeleteConfirm',{count:selectedRows.size})))return;await api('/api/expenses/bulk',{method:'POST',body:JSON.stringify({ids:[...selectedRows],action:bulkAction,value:bulkValue||null})});setSelectedRows(new Set());setBulkAction('');setBulkValue('');await refresh()};
  const show=(key:string)=>columns.includes(key);const colOptions=[['type',t('costs.type')],['category',t('costs.category')],['billing',t('costs.billing')],['month',t('costs.month')],['year',t('costs.year')],['account',t('costs.account')],['status',t('costs.status')],['cancel',t('costs.cancelBy')]];
  return <><div className="section-head"><div><h1>{t('costs.title')}</h1><p>{t('costs.sub')}</p></div><button onClick={onAdd}><Plus size={18}/>{t('new.entry')}</button></div>
  <div className="toolbar card advanced-toolbar"><div className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={t('costs.search')}/></div><div className="segmented compact-segmented"><button className={typeFilter==='all'?'active':''} onClick={()=>setTypeFilter('all')}>{t('filter.all')}</button><button className={typeFilter==='expense'?'active':''} onClick={()=>setTypeFilter('expense')}>{t('type.expenses')}</button><button className={typeFilter==='income'?'active':''} onClick={()=>setTypeFilter('income')}>{t('type.incomes')}</button></div><details className="table-tools"><summary><ListFilter size={15}/>{t('costs.filters')}</summary><div className="table-tools-menu"><label>{t('form.tags')}<input value={filter.tag} onChange={e=>setFilter({...filter,tag:e.target.value})}/></label><div className="range-row"><label>{t('costs.minMonth')}<input type="number" value={filter.min} onChange={e=>setFilter({...filter,min:e.target.value})}/></label><label>{t('costs.maxMonth')}<input type="number" value={filter.max} onChange={e=>setFilter({...filter,max:e.target.value})}/></label></div><label className="check"><input type="checkbox" checked={filter.autoRenew} onChange={e=>setFilter({...filter,autoRenew:e.target.checked})}/>{t('form.autoRenew')}</label><label className="check"><input type="checkbox" checked={filter.uncategorized} onChange={e=>setFilter({...filter,uncategorized:e.target.checked})}/>{t('costs.onlyUncategorized')}</label><button className="secondary wide" onClick={resetFilters}>{t('costs.resetFilters')}</button></div></details><details className="table-tools"><summary>{t('costs.columns')}</summary><div className="table-tools-menu">{colOptions.map(([id,label])=><label className="check" key={id}><input type="checkbox" checked={columns.includes(id)} onChange={()=>setColumns(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id])}/>{label}</label>)}</div></details><span>{t('costs.entries',{count:rows.length})}</span></div>
  <div className="saved-view-bar"><select defaultValue="" onChange={e=>{if(e.target.value)loadView(e.target.value);e.target.value=''}}><option value="">{t('costs.savedViews')}</option>{Object.keys(savedViews).map(n=><option key={n} value={n}>{n}</option>)}</select><input value={viewName} onChange={e=>setViewName(e.target.value)} placeholder={t('costs.viewName')}/><button className="secondary" onClick={saveView}>{t('costs.saveView')}</button>{Object.keys(savedViews).length>0&&<button className="text-btn danger-text" onClick={()=>{if(confirm(t('costs.deleteViewsConfirm')))setSavedViews({})}}>{t('costs.clearViews')}</button>}</div>
  {selectedRows.size>0&&<div className="bulk-bar card"><strong>{t('costs.selectedCount',{count:selectedRows.size})}</strong><select value={bulkAction} onChange={e=>{setBulkAction(e.target.value);setBulkValue('')}}><option value="">{t('costs.bulkAction')}</option><option value="status">{t('costs.changeStatus')}</option><option value="category">{t('costs.changeCategory')}</option><option value="account">{t('costs.changeAccount')}</option><option value="delete">{t('delete')}</option></select>{bulkAction==='status'&&<select value={bulkValue} onChange={e=>setBulkValue(e.target.value)}><option value="active">{t('form.active')}</option><option value="paused">{t('form.paused')}</option><option value="cancelled">{t('form.cancelled')}</option><option value="ended">{t('form.ended')}</option></select>}{bulkAction==='category'&&<select value={bulkValue} onChange={e=>setBulkValue(e.target.value)}><option value="">{t('form.noCategory')}</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>}{bulkAction==='account'&&<select value={bulkValue} onChange={e=>setBulkValue(e.target.value)}><option value="">{t('form.noAccount')}</option>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select>}<button onClick={bulk} disabled={!bulkAction}>{t('apply')}</button><button className="secondary" onClick={()=>setSelectedRows(new Set())}>{t('cancel')}</button></div>}
  <div className="table-card card"><table><thead><tr><th className="select-col"><input type="checkbox" checked={rows.length>0&&rows.every(x=>selectedRows.has(x.id))} onChange={e=>setSelectedRows(e.target.checked?new Set(rows.map(x=>x.id)):new Set())}/></th><th>{header(t('costs.name'),'name')}</th>{show('type')&&<th>{header(t('costs.type'),'type')}</th>}{show('category')&&<th>{header(t('costs.category'),'category',checkboxList('categories',categories.map(c=>({id:String(c.id),name:c.name}))))}</th>}{show('billing')&&<th>{header(t('costs.billing'),'billing',checkboxList('billing',['monthly','quarterly','halfyearly','yearly','custom'].map(id=>({id,name:t(`interval.${id}`)}))))}</th>}{show('month')&&<th>{header(t('costs.month'),'month')}</th>}{show('year')&&<th>{header(t('costs.year'),'year')}</th>}{show('account')&&<th>{header(t('costs.account'),'account',checkboxList('accounts',accounts.map(a=>({id:String(a.id),name:a.name}))))}</th>}{show('status')&&<th>{header(t('costs.status'),'status',checkboxList('statuses',['active','paused','cancelled','ended'].map(id=>({id,name:t(`form.${id}`)}))))}</th>}{show('cancel')&&<th>{header(t('costs.cancelBy'),'cancel')}</th>}<th></th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td><input type="checkbox" checked={selectedRows.has(x.id)} onChange={()=>setSelectedRows(v=>{const n=new Set(v);n.has(x.id)?n.delete(x.id):n.add(x.id);return n})}/></td><td><div className="name-cell"><div className={`mini-icon ${x.entry_type==='income'?'income-icon':''}`}>{x.name[0].toUpperCase()}</div><div><strong>{x.name}</strong><span>{x.provider||'–'}</span>{x.amount_estimated&&<small className="estimated-label">≈ {t('form.estimated')}</small>}{x.tags&&<small className="tag-line">{x.tags}</small>}</div></div></td>{show('type')&&<td><span className={`pill type-pill ${x.entry_type}`}>{x.entry_type==='income'?t('type.income'):t('type.expense')}</span></td>}{show('category')&&<td><span className="pill category-pill" style={{'--category-color':x.category_color||'#7B8798'} as any}>{x.category||t('costs.noCategory')}</span></td>}{show('billing')&&<td>{interval(x)}<small className="cell-sub">{money(x.amount)}</small></td>}{show('month')&&<td><strong>{money(x.monthly_equivalent)}</strong></td>}{show('year')&&<td>{money(x.yearly_equivalent)}</td>}{show('account')&&<td>{x.account||'–'}</td>}{show('status')&&<td><span className={`status-badge ${x.status}`}>{t(`form.${x.status}`)}</span>{x.auto_renew&&<small className="cell-sub">↻ {x.renewal_amount?money(x.renewal_amount):t('form.autoRenew')}</small>}</td>}{show('cancel')&&<td>{x.entry_type==='income'?'–':dateFmt(x.effective_cancellation_date||x.cancellation_date)}<small className="cell-sub">{x.entry_type==='income'?'':x.minimum_term_months?t('costs.term',{count:x.minimum_term_months}):x.effective_contract_end?t('costs.until',{date:dateFmt(x.effective_contract_end)}):''}</small></td>}<td><div className="row-actions">{x.contract_url&&<a className="icon-link" href={x.contract_url} target="_blank" rel="noreferrer" title={t('costs.openContract')}>↗</a>}<button className="icon-btn" title={t('clone')} onClick={()=>onClone(x)}><Copy size={16}/></button><button className="icon-btn" title={t('edit')} onClick={()=>onEdit(x)}><Pencil size={16}/></button><button className="icon-btn danger" title={t('delete')} onClick={()=>onDelete(x)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table>{!rows.length&&<div className="empty">{t('costs.empty')}</div>}</div></>
}


function Accounts({accounts,categories,refresh,isAdmin}:{accounts:Account[];categories:Category[];refresh:()=>Promise<void>;isAdmin:boolean}){
  const{t}=useI18n();
  const[msg,setMsg]=useState('');
  const[accountName,setAccountName]=useState('');const[accountKind,setAccountKind]=useState('bank');const[accountScope,setAccountScope]=useState<'private'|'global'>(isAdmin?'global':'private');const[editingAccount,setEditingAccount]=useState<Account|null>(null);
  const[categoryName,setCategoryName]=useState('');const[categoryColor,setCategoryColor]=useState('#5B5CF0');const[categoryScope,setCategoryScope]=useState<'private'|'global'>(isAdmin?'global':'private');const[editingCategory,setEditingCategory]=useState<Category|null>(null);
  const resetAccount=()=>{setEditingAccount(null);setAccountName('');setAccountKind('bank');setAccountScope(isAdmin?'global':'private')};
  const resetCategory=()=>{setEditingCategory(null);setCategoryName('');setCategoryColor('#5B5CF0');setCategoryScope(isAdmin?'global':'private')};
  const saveAccount=async(e:any)=>{e.preventDefault();if(!accountName.trim())return;setMsg('');try{if(editingAccount)await api(`/api/accounts/${editingAccount.id}`,{method:'PATCH',body:JSON.stringify({name:accountName,kind:accountKind})});else await api('/api/accounts',{method:'POST',body:JSON.stringify({name:accountName,kind:accountKind,note:'',scope:isAdmin?accountScope:'private'})});resetAccount();await refresh()}catch(x:any){setMsg(x.message)}};
  const saveCategory=async(e:any)=>{e.preventDefault();if(!categoryName.trim())return;setMsg('');try{if(editingCategory)await api(`/api/categories/${editingCategory.id}`,{method:'PATCH',body:JSON.stringify({name:categoryName,color:categoryColor})});else await api('/api/categories',{method:'POST',body:JSON.stringify({name:categoryName,icon:'wallet',color:categoryColor,scope:isAdmin?categoryScope:'private'})});resetCategory();await refresh()}catch(x:any){setMsg(x.message)}};
  const remove=async(type:'accounts'|'categories',item:Account|Category)=>{const global=item.scope==='global';const hide=global&&!isAdmin;if(global&&isAdmin&&!confirm(t('accounts.confirmGlobal',{name:item.name})))return;if(!global&&!confirm(t('accounts.confirmPrivate',{name:item.name})))return;setMsg('');try{await api(`/api/${type}/${item.id}`,{method:'DELETE'});setMsg(hide?t('accounts.hidden'):t('accounts.deleted'));await refresh()}catch(e:any){setMsg(e.message)}};
  const resetHidden=async()=>{setMsg('');try{const r=await api<{restored:number}>('/api/catalog/reset-hidden',{method:'POST'});setMsg(t('accounts.restored',{count:r.restored}));await refresh()}catch(e:any){setMsg(e.message)}};
  const kindLabel=(kind:string)=>t(`accountKind.${kind==='credit_card'?'creditCard':kind==='debit_card'?'debitCard':kind==='direct_debit'?'directDebit':kind}`);
  return <><div className="section-head"><div><h1>{t('accounts.title')}</h1><p>{t('accounts.catalogSub')}</p></div><button className="ghost" onClick={resetHidden}><RotateCcw size={16}/>{t('accounts.restore')}</button></div>{msg&&<div className="catalog-message">{msg}</div>}<div className="two-col catalog-grid">
    <article className="card settings-card catalog-card"><div className="card-head"><div><h2>{t('accounts.payments')}</h2><p>{t('accounts.paymentsSub')}</p></div><Landmark size={20}/></div><form className="catalog-editor" onSubmit={saveAccount}><input value={accountName} onChange={e=>setAccountName(e.target.value)} placeholder={t('accounts.newPrivate')}/><select value={accountKind} onChange={e=>setAccountKind(e.target.value)}><option value="bank">{t('accountKind.bank')}</option><option value="credit_card">{t('accountKind.creditCard')}</option><option value="debit_card">{t('accountKind.debitCard')}</option><option value="paypal">PayPal</option><option value="direct_debit">{t('accountKind.directDebit')}</option><option value="cash">{t('accountKind.cash')}</option><option value="other">{t('accountKind.other')}</option></select>{isAdmin&&!editingAccount&&<select value={accountScope} onChange={e=>setAccountScope(e.target.value as any)}><option value="global">{t('catalog.global')}</option><option value="private">{t('catalog.private')}</option></select>}<button disabled={!accountName.trim()}>{editingAccount?t('save'):t('create')}</button>{editingAccount&&<button type="button" className="secondary" onClick={resetAccount}>{t('cancel')}</button>}</form><div className="manage-list rich-manage-list">{accounts.map(a=><div key={a.id}><span><Landmark size={17}/><div><strong>{a.name}</strong><small>{kindLabel(a.kind)} · {a.scope==='global'?t('catalog.globalTemplate'):t('catalog.private')}</small></div></span><div className="catalog-row-actions">{a.can_edit&&<button className="icon-btn" title={t('edit')} onClick={()=>{setEditingAccount(a);setAccountName(a.name);setAccountKind(a.kind)}}><Pencil size={15}/></button>}<button className="icon-btn danger" title={a.scope==='global'&&!isAdmin?t('hide.mine'):t('delete')} onClick={()=>remove('accounts',a)}>{a.scope==='global'&&!isAdmin?<EyeOff size={15}/>:<Trash2 size={15}/>}</button></div></div>)}</div></article>
    <article className="card settings-card catalog-card"><div className="card-head"><div><h2>{t('categories.title')}</h2><p>{t('categories.sub')}</p></div><WalletCards size={20}/></div><form className="catalog-editor" onSubmit={saveCategory}><input value={categoryName} onChange={e=>setCategoryName(e.target.value)} placeholder={t('categories.newPrivate')}/><input className="catalog-color" type="color" value={categoryColor} onChange={e=>setCategoryColor(e.target.value)}/>{isAdmin&&!editingCategory&&<select value={categoryScope} onChange={e=>setCategoryScope(e.target.value as any)}><option value="global">{t('catalog.global')}</option><option value="private">{t('catalog.private')}</option></select>}<button disabled={!categoryName.trim()}>{editingCategory?t('save'):t('create')}</button>{editingCategory&&<button type="button" className="secondary" onClick={resetCategory}>{t('cancel')}</button>}</form><div className="manage-list rich-manage-list">{categories.map(c=><div key={c.id}><span><WalletCards size={17}/><i className="category-mini-dot" style={{background:c.color}}></i><div><strong>{c.name}</strong><small>{c.scope==='global'?t('catalog.globalTemplate'):t('catalog.private')}</small></div></span><div className="catalog-row-actions">{c.can_edit&&<button className="icon-btn" title={t('edit')} onClick={()=>{setEditingCategory(c);setCategoryName(c.name);setCategoryColor(c.color)}}><Pencil size={15}/></button>}<button className="icon-btn danger" title={c.scope==='global'&&!isAdmin?t('hide.mine'):t('delete')} onClick={()=>remove('categories',c)}>{c.scope==='global'&&!isAdmin?<EyeOff size={15}/>:<Trash2 size={15}/>}</button></div></div>)}</div></article>
  </div></>
}

function AIFormattedResult({text}:{text:string}){
  const inline=(value:string)=>value.split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map((part,i)=>part.startsWith('**')&&part.endsWith('**')?<strong key={i}>{part.slice(2,-2)}</strong>:<span key={i}>{part}</span>);
  const lines=text.replace(/<think>[\s\S]*?<\/think>/gi,'').split(/\r?\n/);const nodes:any[]=[];let bullets:string[]=[];const flush=()=>{if(bullets.length){nodes.push(<ul key={`u-${nodes.length}`}>{bullets.map((x,i)=><li key={i}>{inline(x)}</li>)}</ul>);bullets=[]}};
  lines.forEach((raw,i)=>{const line=raw.trim();if(!line){flush();return}if(/^#{1,3}\s+/.test(line)){flush();nodes.push(<h3 key={`h-${i}`}>{inline(line.replace(/^#{1,3}\s+/,''))}</h3>)}else if(/^[-*•]\s+/.test(line)){bullets.push(line.replace(/^[-*•]\s+/,''))}else if(/^\d+[.)]\s+/.test(line)){bullets.push(line.replace(/^\d+[.)]\s+/,''))}else{flush();nodes.push(<p key={`p-${i}`}>{inline(line)}</p>)}});flush();return <div className="analysis-rich">{nodes}</div>
}

function AISelectionModal({expenses,selected,setSelected,onClose}:{expenses:Expense[];selected:Set<number>;setSelected:(x:Set<number>)=>void;onClose:()=>void}){
  const{t}=useI18n();const[q,setQ]=useState('');const[type,setType]=useState<'all'|'expense'|'income'>('all');
  const rows=expenses.filter(x=>(type==='all'||x.entry_type===type)&&(x.name+' '+x.provider+' '+(x.category||'')).toLowerCase().includes(q.toLowerCase()));
  const groups=Object.entries(rows.reduce((m:Record<string,Expense[]>,x)=>{const k=x.category||t('costs.noCategory');(m[k] ||= []).push(x);return m},{})).sort((a,b)=>a[0].localeCompare(b[0]));
  const toggle=(id:number)=>{const n=new Set(selected);n.has(id)?n.delete(id):n.add(id);setSelected(n)};
  const toggleGroup=(items:Expense[])=>{const n=new Set(selected);const all=items.every(x=>n.has(x.id));items.forEach(x=>all?n.delete(x.id):n.add(x.id));setSelected(n)};
  return <Modal title={t('ai.dataTitle')} onClose={onClose}><div className="ai-selection-modal"><div className="ai-selection-toolbar"><div className="search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={t('ai.dataSearch')}/></div><div className="segmented"><button type="button" className={type==='all'?'active':''} onClick={()=>setType('all')}>{t('filter.all')}</button><button type="button" className={type==='expense'?'active':''} onClick={()=>setType('expense')}>{t('type.expenses')}</button><button type="button" className={type==='income'?'active':''} onClick={()=>setType('income')}>{t('type.incomes')}</button></div></div><div className="ai-selection-actions"><span>{t('ai.dataSelected',{selected:selected.size,total:expenses.length})}</span><button type="button" className="text-btn" onClick={()=>setSelected(new Set(selected.size===expenses.length?[]:expenses.map(x=>x.id)))}>{selected.size===expenses.length?t('selection.none'):t('selection.all')}</button></div><div className="ai-category-groups">{groups.map(([name,items])=><details key={name}><summary><span><i style={{background:items[0]?.category_color||'#7B8798'}}></i>{name}<small>{items.filter(x=>selected.has(x.id)).length}/{items.length}</small></span><button type="button" className="text-btn" onClick={e=>{e.preventDefault();toggleGroup(items)}}>{items.every(x=>selected.has(x.id))?t('selection.none'):t('selection.all')}</button></summary><div>{items.map(x=><button type="button" key={x.id} className={selected.has(x.id)?'ai-select-row selected':'ai-select-row'} onClick={()=>toggle(x.id)}><span className="check-dot">{selected.has(x.id)&&<CheckCircle2 size={14}/>}</span><div><strong>{x.name}</strong><small>{x.provider||x.category||'–'}</small></div><span className={`pill type-pill ${x.entry_type}`}>{x.entry_type==='income'?t('type.income'):t('type.expense')}</span><b>{money(x.monthly_equivalent)}</b></button>)}</div></details>)}</div><div className="form-actions"><button type="button" onClick={onClose}>{t('ai.dataDone')}</button></div></div></Modal>
}

function AIPage({expenses,isAdmin}:{expenses:Expense[];isAdmin:boolean}){
  const{t,language}=useI18n();const[profiles,setProfiles]=useState<AIProfile[]>([]);const[profileId,setProfileId]=useState<number|''>('');const[conversations,setConversations]=useState<AIConversation[]>([]);const[conversation,setConversation]=useState<AIConversation|null>(null);const[selected,setSelected]=useState<Set<number>>(new Set(expenses.map(x=>x.id)));const[mode,setMode]=useState<'analysis'|'savings'>('analysis');const[target,setTarget]=useState('80');const[input,setInput]=useState('');const[dataOpen,setDataOpen]=useState(false);const[brain,setBrain]=useState<AIBrain>({summary:'',updated_at:null});const[brainOpen,setBrainOpen]=useState(false);const[brainDraft,setBrainDraft]=useState('');const[error,setError]=useState('');
  const loadConversations=async()=>{const list=await api<AIConversation[]>('/api/ai/conversations');setConversations(list);return list};
  const loadConversation=async(id:number)=>{const x=await api<AIConversation>(`/api/ai/conversations/${id}`);setConversation(x);setSelected(new Set(x.selected_expense_ids||[]));setMode(x.mode==='savings'?'savings':'analysis');if(x.target_savings!=null)setTarget(String(x.target_savings));if(x.profile_id)setProfileId(x.profile_id);return x};
  useEffect(()=>{(async()=>{try{const[p,list,b]=await Promise.all([api<AIProfile[]>('/api/ai/profiles'),api<AIConversation[]>('/api/ai/conversations'),api<AIBrain>('/api/ai/brain')]);setProfiles(p);setProfileId(p[0]?.id||'');setConversations(list);setBrain(b);setBrainDraft(b.summary||'');if(list[0]){const x=await api<AIConversation>(`/api/ai/conversations/${list[0].id}`);setConversation(x);setSelected(new Set(x.selected_expense_ids||expenses.map(e=>e.id)));if(x.profile_id)setProfileId(x.profile_id);setMode(x.mode==='savings'?'savings':'analysis');if(x.target_savings!=null)setTarget(String(x.target_savings))}}catch(e:any){setError(e.message)}})()},[]);
  useEffect(()=>{if(conversation)return;setSelected(new Set(expenses.map(x=>x.id)))},[expenses.map(x=>x.id).join(','),conversation?.id]);
  useEffect(()=>{if(!conversation||conversation.status!=='running')return;const timer=setInterval(async()=>{try{const x=await loadConversation(conversation.id);if(x.status!=='running'){await loadConversations();const b=await api<AIBrain>('/api/ai/brain');setBrain(b);setBrainDraft(b.summary||'')}}catch{}},2200);return()=>clearInterval(timer)},[conversation?.id,conversation?.status]);
  const selectedRows=expenses.filter(x=>selected.has(x.id));const totalOut=selectedRows.filter(x=>x.entry_type!=='income').reduce((s,x)=>s+x.monthly_equivalent,0);const totalInc=selectedRows.filter(x=>x.entry_type==='income').reduce((s,x)=>s+x.monthly_equivalent,0);
  const startNew=()=>{setConversation(null);setSelected(new Set(expenses.map(x=>x.id)));setMode('analysis');setTarget('80');setInput('');setError('')};
  const send=async(message:string,initial=false)=>{const text=message.trim();if(!text||!profileId||!selected.size)return;setError('');try{let conv=conversation;if(!conv){conv=await api<AIConversation>('/api/ai/conversations',{method:'POST',body:JSON.stringify({profile_id:profileId,mode:initial?mode:'chat',target_savings:initial&&mode==='savings'?Number(target||0):null,expense_ids:[...selected]})});setConversation(conv);await loadConversations()}const updated=await api<AIConversation>(`/api/ai/conversations/${conv.id}/messages`,{method:'POST',body:JSON.stringify({message:text,profile_id:profileId,expense_ids:[...selected],mode:initial?mode:'chat',target_savings:initial&&mode==='savings'?Number(target||0):conv.target_savings,language})});setConversation(updated);setInput('');await loadConversations()}catch(e:any){setError(e.message)}};
  const runInitial=()=>send(mode==='savings'?t('ai.savingsStart',{amount:money(Number(target||0))}):t('ai.analysisStart'),true);
  const saveBrain=async()=>{try{const b=await api<AIBrain>('/api/ai/brain',{method:'PUT',body:JSON.stringify({summary:brainDraft})});setBrain(b);setBrainDraft(b.summary||'');setBrainOpen(false)}catch(e:any){setError(e.message)}};
  const deleteConversation=async(id:number)=>{try{await api(`/api/ai/conversations/${id}`,{method:'DELETE'});if(conversation?.id===id)startNew();await loadConversations()}catch(e:any){setError(e.message)}};
  const messages=conversation?.messages||[];const running=conversation?.status==='running';const selectedProfile=profiles.find(p=>p.id===profileId);
  const quickPrompts=language==='de'?['Welche 5 Ausgaben haben den größten Hebel?','Welche Verträge oder Kündigungsfristen sollte ich dieses Jahr prüfen?','Welche Kosten haben sich erhöht oder werden sich erhöhen?','Erkennst du doppelte oder überlappende Leistungen?','Erkläre mir meinen Forecast und die größten Veränderungen.']:['Which 5 expenses have the biggest optimization potential?','Which contracts or cancellation deadlines should I review this year?','Which costs increased or will increase?','Do you see duplicate or overlapping services?','Explain my forecast and the biggest changes.'];
  return <><div className="section-head"><div><h1>{t('ai.agentTitle')}</h1><p>{t('ai.agentSub')}</p></div><button className="secondary" onClick={startNew}><MessageSquarePlus size={17}/>{t('ai.newChat')}</button></div>{dataOpen&&<AISelectionModal expenses={expenses} selected={selected} setSelected={setSelected} onClose={()=>setDataOpen(false)}/>}<div className="ai-agent-layout"><aside className="card ai-agent-sidebar"><button className="ai-new-chat" onClick={startNew}><Plus size={16}/>{t('ai.newChat')}</button><div className="ai-history-head"><span>{t('ai.history')}</span><small>{conversations.length}</small></div><div className="ai-history-list">{conversations.map(c=><div key={c.id} className={conversation?.id===c.id?'ai-history-item active':'ai-history-item'}><button onClick={()=>loadConversation(c.id)}><strong>{c.title}</strong><span>{c.status==='running'?t('ai.runningShort'):new Intl.DateTimeFormat(localeFor(language),{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(c.updated_at))}</span></button>{c.status!=='running'&&<button className="icon-btn danger" title={t('delete')} onClick={()=>deleteConversation(c.id)}><Trash2 size={14}/></button>}</div>)}{!conversations.length&&<div className="empty small">{t('ai.noHistory')}</div>}</div><div className="ai-brain"><button className="ai-brain-head" onClick={()=>setBrainOpen(v=>!v)}><span><BookOpen size={16}/><strong>{t('ai.brain')}</strong></span><ChevronDown size={15}/></button><p>{brain.summary?t('ai.brainStored'):t('ai.brainEmpty')}</p>{brainOpen&&<div className="ai-brain-editor"><textarea rows={8} value={brainDraft} onChange={e=>setBrainDraft(e.target.value)} placeholder={t('ai.brainPlaceholder')}/><div><button className="secondary" onClick={()=>{setBrainDraft(brain.summary||'');setBrainOpen(false)}}>{t('cancel')}</button><button onClick={saveBrain}>{t('save')}</button></div></div>}</div></aside><section className="card ai-agent-main"><div className="ai-agent-top"><div><div className="ai-orb compact-orb"><Sparkles size={22}/></div><div><h2>{conversation?.title||t('ai.agentWelcome')}</h2><p>{running?t('ai.backgroundHint'):t('ai.agentReady')}</p></div></div><div className="ai-agent-controls"><select value={profileId} onChange={e=>setProfileId(e.target.value?Number(e.target.value):'')}><option value="">{t('ai.noneProfile')}</option>{profiles.map(p=><option key={p.id} value={p.id}>{p.name} · {p.model}</option>)}</select><button className="secondary" onClick={()=>setDataOpen(true)}><ListFilter size={16}/>{t('ai.dataButton',{selected:selected.size,total:expenses.length})}</button></div></div><div className="ai-context-grid agent-context"><div><span>{t('type.expenses')}</span><b>{money(totalOut)}</b></div><div><span>{t('type.incomes')}</span><b>{money(totalInc)}</b></div><div><span>{t('stat.delta')}</span><b className={totalInc-totalOut<0?'negative':'positive'}>{money(totalInc-totalOut)}</b></div><div><span>{t('ai.contextEntries')}</span><b>{selectedRows.length}</b></div><div><span>{t('ai.contextCategories')}</span><b>{new Set(selectedRows.map(x=>x.category||t('costs.noCategory'))).size}</b></div></div>{!conversation&&<div className="ai-start-panel"><h3>{t('ai.startQuestion')}</h3><div className="ai-mode-grid"><button className={mode==='analysis'?'ai-mode-card active':'ai-mode-card'} onClick={()=>setMode('analysis')}><Sparkles size={20}/><span><strong>{t('ai.modeAnalysis')}</strong><small>{t('ai.modeAnalysisSub')}</small></span></button><button className={mode==='savings'?'ai-mode-card active':'ai-mode-card'} onClick={()=>setMode('savings')}><Target size={20}/><span><strong>{t('ai.modeSavings')}</strong><small>{t('ai.modeSavingsSub')}</small></span></button></div>{mode==='savings'&&<label className="ai-target">{t('ai.savingsTarget')}<div><input type="number" min="1" step="1" value={target} onChange={e=>setTarget(e.target.value)}/><span>€/Monat</span></div></label>}<button className="wide" disabled={!profileId||!selected.size||(mode==='savings'&&Number(target)<=0)} onClick={runInitial}><Sparkles size={17}/>{mode==='savings'?t('ai.startSavings'):t('ai.startAnalysis')}</button>{selectedProfile&&<small>{selectedProfile.provider_label} · {selectedProfile.model}</small>}</div>}{conversation&&<div className="ai-chat"><div className="ai-messages">{messages.map(m=><div key={m.id} className={`ai-message ${m.role}`}><div className="ai-message-meta">{m.role==='assistant'?'PenguCost AI':t('ai.you')}</div>{m.role==='assistant'?<AIFormattedResult text={m.content}/>:<p>{m.content}</p>}</div>)}{running&&<div className="ai-running"><LoaderCircle className="spin" size={20}/><div><strong>{t('ai.running')}</strong><span>{t('ai.backgroundHint')}</span></div></div>}{conversation.status==='error'&&<div className="error">{conversation.last_error||t('ai.failed')}</div>}</div><div className="ai-quick-prompts">{quickPrompts.map(q=><button key={q} type="button" disabled={running} onClick={()=>send(q)}>{q}</button>)}</div><div className="ai-composer"><textarea rows={2} value={input} disabled={running} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(input.trim())send(input)}}} placeholder={t('ai.askPlaceholder')}/><button disabled={running||!input.trim()||!profileId} onClick={()=>send(input)}><Send size={18}/></button></div></div>}{error&&<div className="error ai-agent-error">{error}{isAdmin?t('ai.checkProfile'):''}</div>}{!profiles.length&&<div className="settings-hint"><Server size={16}/><span>{isAdmin?t('ai.adminMissing'):t('ai.userMissing')}</span></div>}</section></div></>
}

function UsersPage(){
  const{t}=useI18n();const[users,setUsers]=useState<User[]>([]);const[show,setShow]=useState(false);const[name,setName]=useState('');const[display,setDisplay]=useState('');const[pwd,setPwd]=useState('');const[resetUser,setResetUser]=useState<User|null>(null);const[resetPwd,setResetPwd]=useState('');const[resetConfirm,setResetConfirm]=useState('');const[resetMsg,setResetMsg]=useState('');const load=()=>api<User[]>('/api/users').then(setUsers);useEffect(()=>{load()},[]);
  const closeReset=()=>{setResetUser(null);setResetPwd('');setResetConfirm('');setResetMsg('')};
  const resetPassword=async(e:FormEvent)=>{e.preventDefault();if(!resetUser)return;if(resetPwd!==resetConfirm){setResetMsg(t('password.mismatch'));return}setResetMsg(t('settings.saving'));try{await api(`/api/users/${resetUser.id}/password`,{method:'PUT',body:JSON.stringify({password:resetPwd})});setResetMsg(t('password.resetDone'));setTimeout(closeReset,600)}catch(x:any){setResetMsg(x.message)}};
  return <><div className="section-head"><div><h1>{t('users.title')}</h1><p>{t('users.sub')}</p></div><button onClick={()=>setShow(true)}><Plus size={18}/>{t('users.add')}</button></div><article className="card users-list">{users.map(u=><div key={u.id}><div className="avatar">{(u.display_name||u.username)[0].toUpperCase()}</div><div><strong>{u.display_name||u.username}</strong><span>@{u.username}</span></div><span className="pill">{u.role}</span><button className="icon-btn" title={t('users.resetPassword')} onClick={()=>{setResetUser(u);setResetPwd('');setResetConfirm('');setResetMsg('')}}><KeyRound size={16}/></button><label className="switch"><input type="checkbox" checked={u.is_active!==false} onChange={async e=>{await api(`/api/users/${u.id}`,{method:'PATCH',body:JSON.stringify({is_active:e.target.checked})});load()}}/><i></i></label></div>)}</article>{show&&<Modal title={t('users.modal')} onClose={()=>setShow(false)}><form className="form-grid" onSubmit={async e=>{e.preventDefault();await api('/api/users',{method:'POST',body:JSON.stringify({username:name,display_name:display,password:pwd,role:'member'})});setShow(false);setName('');setDisplay('');setPwd('');load()}}><label>{t('login.username')}<input value={name} onChange={e=>setName(e.target.value)} required/></label><label>{t('login.display')}<input value={display} onChange={e=>setDisplay(e.target.value)}/></label><label className="span2">{t('users.initialPassword')}<input type="password" minLength={8} value={pwd} onChange={e=>setPwd(e.target.value)} required/></label><div className="form-actions span2"><button type="button" className="secondary" onClick={()=>setShow(false)}>{t('cancel')}</button><button>{t('create')}</button></div></form></Modal>}{resetUser&&<Modal title={t('users.resetPassword')} onClose={closeReset}><form className="form-grid" onSubmit={resetPassword}><div className="span2 settings-hint"><KeyRound size={16}/><span>{t('users.resetPasswordFor',{name:resetUser.display_name||resetUser.username})}</span></div><label className="span2">{t('password.new')}<input type="password" minLength={8} autoComplete="new-password" value={resetPwd} onChange={e=>setResetPwd(e.target.value)} required/></label><label className="span2">{t('password.confirm')}<input type="password" minLength={8} autoComplete="new-password" value={resetConfirm} onChange={e=>setResetConfirm(e.target.value)} required/></label>{resetMsg&&<div className="span2 settings-note">{resetMsg}</div>}<div className="form-actions span2"><button type="button" className="secondary" onClick={closeReset}>{t('cancel')}</button><button disabled={resetPwd.length<8||resetConfirm.length<8}>{t('users.resetPassword')}</button></div></form></Modal>}</>
}

function ReminderCenter({reminders,onEdit,onChanged}:{reminders:RemindersResponse;onEdit:(x:ReminderItem)=>void;onChanged:()=>Promise<void>}){
  const{t}=useI18n();const[busy,setBusy]=useState('');const[msg,setMsg]=useState('');const[confirming,setConfirming]=useState<number|null>(null);const[snooze,setSnooze]=useState<Record<number,number>>({});
  const act=async(x:ReminderItem,action:'done'|'cancelled'|'snooze')=>{setBusy(`${x.expense_id}:${action}`);setMsg('');try{await api(`/api/reminders/${x.expense_id}/action`,{method:'POST',body:JSON.stringify({action,event_key:x.event_key,snooze_days:action==='snooze'?(snooze[x.expense_id]||7):undefined})});setConfirming(null);await onChanged()}catch(e:any){setMsg(e.message)}finally{setBusy('')}};
  const kind=(x:ReminderItem)=>x.kind==='auto_renewed'?t('reminders.kindRenewed'):x.kind==='renewal_risk'?t('reminders.kindRisk'):t('reminders.kindDue');
  return <div className="reminder-center"><div className="reminder-summary"><div className="reminder-orb"><Bell size={22}/></div><div><strong>{reminders.count?(reminders.count===1?t('reminders.attentionOne'):t('reminders.attentionMany',{count:reminders.count})):t('reminders.ok')}</strong><span>{t('reminders.lead',{count:reminders.reminder_days})}</span>{msg&&<span className="reminder-error">{msg}</span>}</div></div>{reminders.items.length?<div className="reminder-list">{reminders.items.map(x=><div key={`${x.expense_id}:${x.event_key}`} className="reminder-item"><i style={{background:x.category_color||'#7B8798'}}></i><div className="reminder-item-body"><button className="reminder-main" onClick={()=>onEdit(x)}><div><div className="reminder-item-head"><strong>{x.name}</strong><span className={`reminder-kind ${x.kind}`}>{kind(x)}</span></div><span>{x.provider||x.category||t('contract')} · {t('reminders.cancelBy',{date:dateFmt(x.cancellation_date)})} · {t('reminders.end',{date:dateFmt(x.contract_end)})}</span>{x.days_remaining!==null&&x.days_remaining>=0&&<small>{x.days_remaining===0?t('reminders.today'):t('reminders.daysLeft',{count:x.days_remaining})}</small>}{x.kind==='auto_renewed'&&<small>{t('reminders.renewed',{period:x.renewal_period_months?` (${t('interval.months',{count:x.renewal_period_months})})`:''})}</small>}</div><ChevronRight size={18}/></button><div className="reminder-actions"><button className="secondary mini-action" disabled={!!busy} onClick={()=>act(x,'done')}><CheckCircle2 size={14}/>{busy===`${x.expense_id}:done`?'…':t('reminders.done')}</button>{(x.days_remaining??0)>0&&<div className="snooze-control"><select value={snooze[x.expense_id]||7} onChange={e=>setSnooze({...snooze,[x.expense_id]:Number(e.target.value)})}><option value={1}>{t('reminders.day')}</option><option value={3}>{t('reminders.days3')}</option><option value={7}>{t('reminders.days7')}</option><option value={14}>{t('reminders.days14')}</option><option value={30}>{t('reminders.days30')}</option></select><button className="secondary mini-action" disabled={!!busy} onClick={()=>act(x,'snooze')}><Bell size={14}/>{busy===`${x.expense_id}:snooze`?'…':t('reminders.later')}</button></div>}<button className={`mini-action cancel-action ${confirming===x.expense_id?'confirming':''}`} disabled={!!busy} onClick={()=>{if(confirming===x.expense_id)act(x,'cancelled');else setConfirming(x.expense_id)}}><X size={14}/>{busy===`${x.expense_id}:cancelled`?'…':confirming===x.expense_id?t('reminders.confirm'):t('reminders.cancelled')}</button></div></div></div>)}</div>:<div className="empty reminder-empty"><CheckCircle2 size={30}/><strong>{t('reminders.none')}</strong><span>{t('reminders.noneSub')}</span></div>}</div>
}

function AIProfilesAdmin(){
  const{t}=useI18n();const[providers,setProviders]=useState<AIProvider[]>([]);const[profiles,setProfiles]=useState<AIProfile[]>([]);const[editing,setEditing]=useState<AIProfile|null>(null);const[key,setKey]=useState('');const[msg,setMsg]=useState('');
  const blank={name:'',provider:'ollama',base_url:'http://127.0.0.1:11434/v1',model:'',enabled:true};const[form,setForm]=useState<any>(blank);
  const load=async()=>{const[p,ps]=await Promise.all([api<AIProvider[]>('/api/ai/providers'),api<AIProfile[]>('/api/settings/ai/profiles')]);setProviders(p);setProfiles(ps)};useEffect(()=>{load().catch(e=>setMsg(e.message))},[]);
  const chooseProvider=(id:string)=>{const p=providers.find(x=>x.id===id);setForm((f:any)=>({...f,provider:id,base_url:p?.default_base_url??''}))};const reset=()=>{setEditing(null);setKey('');const p=providers.find(x=>x.id==='ollama');setForm({...blank,base_url:p?.default_base_url||blank.base_url})};
  const save=async()=>{setMsg(t('settings.saving'));try{const body={...form,api_key:key};if(editing)await api(`/api/settings/ai/profiles/${editing.id}`,{method:'PUT',body:JSON.stringify(body)});else await api('/api/settings/ai/profiles',{method:'POST',body:JSON.stringify(body)});setMsg(t('settings.saved'));reset();await load()}catch(e:any){setMsg(e.message)}};
  return <article className="card settings-card"><div className="card-head"><div><h2>{t('settings.aiTitle')}</h2><p>{t('settings.aiSub')}</p></div><BrainCircuit size={20}/></div><div className="ai-profile-list">{profiles.map(p=><div key={p.id} className="ai-profile-row"><div><strong>{p.name}</strong><span>{p.provider_label} · {p.model}</span><small>{p.base_url||t('settings.aiEndpointDefault')} · {p.has_api_key?t('settings.aiKeySet'):t('settings.aiNoKey')}</small></div><span className={`pill ${p.enabled?'':'muted-pill'}`}>{p.enabled?t('settings.aiActive'):t('settings.aiInactive')}</span><button className="icon-btn" title={t('edit')} onClick={()=>{setEditing(p);setKey('');setForm({name:p.name,provider:p.provider,base_url:p.base_url||'',model:p.model,enabled:p.enabled})}}><Pencil size={15}/></button><button className="icon-btn danger" title={t('delete')} onClick={async()=>{if(!confirm(`${t('delete')}: ${p.name}?`))return;await api(`/api/settings/ai/profiles/${p.id}`,{method:'DELETE'});await load()}}><Trash2 size={15}/></button></div>)}{!profiles.length&&<div className="empty small">{t('settings.aiNo')}</div>}</div><div className="ai-profile-editor"><div className="editor-title"><strong>{editing?t('settings.aiEdit'):t('settings.aiNew')}</strong>{editing&&<button className="text-btn" onClick={reset}>{t('cancel')}</button>}</div><div className="form-grid compact-form"><label>{t('settings.aiName')}<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>{t('settings.aiProvider')}<select value={form.provider} onChange={e=>chooseProvider(e.target.value)}>{providers.map(p=><option key={p.id} value={p.id}>{p.label}</option>)}</select></label><label className="span2">{t('settings.aiBase')}<input value={form.base_url} onChange={e=>setForm({...form,base_url:e.target.value})}/></label><label>{t('settings.aiModel')}<input value={form.model} onChange={e=>setForm({...form,model:e.target.value})}/></label><label>{t('settings.aiKey')}<input type="password" value={key} onChange={e=>setKey(e.target.value)} placeholder={editing?.has_api_key?t('settings.aiKeyKeep'):t('settings.aiKeyOptional')}/></label><label className="check"><input type="checkbox" checked={!!form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/>{t('settings.aiExpose')}</label></div><div className="settings-actions"><span>{msg}</span><button disabled={!form.name||!form.model} onClick={save}>{editing?t('settings.aiSave'):t('settings.aiAdd')}</button></div></div><small>{t('settings.aiFoot')}</small></article>
}

function downloadJson(data:any,name:string){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}

function DataTransferCard({isAdmin,refresh}:{isAdmin:boolean;refresh:()=>Promise<void>}){
  const{t}=useI18n();const userInput=useRef<HTMLInputElement>(null);const adminInput=useRef<HTMLInputElement>(null);const[msg,setMsg]=useState('');
  const readFile=async(file?:File|null)=>{if(!file)return null;try{return JSON.parse(await file.text())}catch{setMsg(t('settings.invalidJson'));return null}};
  const exportUser=async()=>{setMsg('');const data=await api('/api/export/user');downloadJson(data,`pengucost-user-${new Date().toISOString().slice(0,10)}.json`)};
  const importUser=async(file?:File|null)=>{const data=await readFile(file);if(!data||!confirm(t('settings.confirmUserImport')))return;try{const r=await api<{imported_expenses:number;warnings:string[]}>('/api/import/user',{method:'POST',body:JSON.stringify(data)});setMsg(t('settings.importOk',{count:r.imported_expenses})+(r.warnings?.length?` · ${r.warnings.join(', ')}`:''));await refresh()}catch(e:any){setMsg(e.message)}finally{if(userInput.current)userInput.current.value=''}};
  const exportAdmin=async()=>{setMsg('');const data=await api('/api/export/admin');downloadJson(data,`pengucost-full-${new Date().toISOString().slice(0,10)}.json`)};
  const importAdmin=async(file?:File|null)=>{const data=await readFile(file);if(!data||!confirm(t('settings.confirmAdminImport')))return;try{await api('/api/import/admin',{method:'POST',body:JSON.stringify(data)});setMsg(t('settings.importFullOk'));setTimeout(()=>location.reload(),500)}catch(e:any){setMsg(e.message)}finally{if(adminInput.current)adminInput.current.value=''}};
  return <article className="card settings-card"><div className="card-head"><div><h2>{t('settings.data')}</h2><p>{t('settings.dataSub')}</p></div><Database size={20}/></div><div className="data-transfer-grid"><div className="data-transfer-box"><strong>{t('settings.userExport')}</strong><p>{t('settings.userExportHelp')}</p><div className="data-transfer-actions"><button className="secondary" onClick={exportUser}><Download size={16}/>{t('settings.userExport')}</button><button className="secondary" onClick={()=>userInput.current?.click()}><Upload size={16}/>{t('settings.userImport')}</button><input ref={userInput} hidden type="file" accept="application/json,.json" onChange={e=>importUser(e.target.files?.[0])}/></div><small>{t('settings.userImportWarn')}</small></div>{isAdmin&&<div className="data-transfer-box admin-export"><strong>{t('settings.adminExport')}</strong><p>{t('settings.adminExportHelp')}</p><div className="data-transfer-actions"><button onClick={exportAdmin}><Download size={16}/>{t('settings.adminExport')}</button><button className="danger-solid" onClick={()=>adminInput.current?.click()}><Upload size={16}/>{t('settings.adminImport')}</button><input ref={adminInput} hidden type="file" accept="application/json,.json" onChange={e=>importAdmin(e.target.files?.[0])}/></div><small>{t('settings.adminImportWarn')}</small></div>}</div>{msg&&<div className="catalog-message data-message">{msg}</div>}</article>
}

function PasswordSettingsCard(){
  const{t}=useI18n();const[current,setCurrent]=useState('');const[next,setNext]=useState('');const[confirmPwd,setConfirmPwd]=useState('');const[msg,setMsg]=useState('');const[busy,setBusy]=useState(false);
  const submit=async(e:FormEvent)=>{e.preventDefault();if(next!==confirmPwd){setMsg(t('password.mismatch'));return}setBusy(true);setMsg(t('settings.saving'));try{await api('/api/auth/password',{method:'PUT',body:JSON.stringify({current_password:current,new_password:next})});setCurrent('');setNext('');setConfirmPwd('');setMsg(t('password.changed'))}catch(x:any){setMsg(x.message==='Current password is incorrect'?t('password.currentWrong'):x.message==='New password must be different'?t('password.same'):x.message)}finally{setBusy(false)}};
  return <article className="card settings-card"><div className="card-head"><div><h2>{t('password.title')}</h2><p>{t('password.sub')}</p></div><KeyRound size={20}/></div><form className="form-grid compact-form" onSubmit={submit}><label>{t('password.current')}<input type="password" autoComplete="current-password" value={current} onChange={e=>setCurrent(e.target.value)} required/></label><label>{t('password.new')}<input type="password" minLength={8} autoComplete="new-password" value={next} onChange={e=>setNext(e.target.value)} required/></label><label>{t('password.confirm')}<input type="password" minLength={8} autoComplete="new-password" value={confirmPwd} onChange={e=>setConfirmPwd(e.target.value)} required/></label><div className="settings-actions span2"><span>{msg}</span><button disabled={busy||!current||next.length<8||confirmPwd.length<8}>{busy?'…':t('password.change')}</button></div></form><small>{t('password.help')}</small></article>
}

function SettingsPage({theme,setTheme,categories,refresh,refreshReminders,isAdmin,language,setLanguage}:{theme:string;setTheme:(x:string)=>void;categories:Category[];refresh:()=>Promise<void>;refreshReminders:()=>Promise<void>;isAdmin:boolean;language:Language;setLanguage:(x:Language)=>void}){
  const{t}=useI18n();const[reminderDays,setReminderDays]=useState(30);const[reminderMsg,setReminderMsg]=useState('');const[colorMsg,setColorMsg]=useState('');
  useEffect(()=>{api<{cancellation_reminder_days:number}>('/api/settings/reminders').then(x=>setReminderDays(x.cancellation_reminder_days)).catch(()=>{})},[]);
  const changeLanguage=async(next:Language)=>{setLanguage(next);try{await api('/api/settings/preferences',{method:'PUT',body:JSON.stringify({language:next})})}catch{}};
  return <><div className="section-head"><div><h1>{t('settings.title')}</h1><p>{isAdmin?t('settings.subAdmin'):t('settings.subUser')}</p></div></div><div className="settings-stack">
    <article className="card settings-card"><h2>{t('settings.appearance')}</h2><p>{t('settings.appearanceSub')}</p><div className="theme-grid">{themeNames.map(x=><button key={x} className={theme===x?'theme-tile selected':'theme-tile'} onClick={()=>setTheme(x)}><span className={`theme-preview ${x}`}></span><strong>{x[0].toUpperCase()+x.slice(1)}</strong></button>)}</div><div className="language-setting"><div><Languages size={19}/><div><strong>{t('settings.language')}</strong><span>{t('settings.languageSub')}</span></div></div><div className="segmented"><button className={language==='de'?'active':''} onClick={()=>changeLanguage('de')}>{t('settings.german')}</button><button className={language==='en'?'active':''} onClick={()=>changeLanguage('en')}>{t('settings.english')}</button></div></div></article>
    <PasswordSettingsCard/>
    {isAdmin&&<article className="card settings-card"><div className="card-head"><div><h2>{t('settings.categoryColors')}</h2><p>{t('settings.categoryColorsSub')}</p></div><span className="settings-note">{colorMsg}</span></div><div className="category-color-grid">{categories.filter(c=>c.scope==='global').map(c=><div className="category-color-row" key={c.id}><span className="category-dot" style={{background:c.color}}></span><strong>{c.name}</strong><input type="color" value={c.color||'#5B5CF0'} onChange={async e=>{const color=e.target.value;setColorMsg(t('settings.saving'));try{await api(`/api/categories/${c.id}`,{method:'PATCH',body:JSON.stringify({color})});setColorMsg(t('settings.saved'));await refresh()}catch(x:any){setColorMsg(x.message)}}}/><code>{c.color}</code></div>)}</div><small>{t('settings.categoryColorsOnly')}</small></article>}
    <article className="card settings-card"><div className="card-head"><div><h2>{t('settings.reminders')}</h2><p>{t('settings.remindersSub')}</p></div><Bell size={20}/></div><div className="reminder-setting"><label>{t('settings.days')}<input type="number" min="0" max="3650" value={reminderDays} onChange={e=>setReminderDays(Math.max(0,Number(e.target.value||0)))}/><small>{t('settings.daysHelp')}</small></label><button onClick={async()=>{setReminderMsg(t('settings.saving'));try{await api('/api/settings/reminders',{method:'PUT',body:JSON.stringify({cancellation_reminder_days:reminderDays})});await refreshReminders();setReminderMsg(t('settings.saved'))}catch(x:any){setReminderMsg(x.message)}}}>{t('save')}</button></div><div className="settings-hint"><Bell size={16}/><span>{t('settings.reminderHint')}</span></div><span className="settings-note">{reminderMsg}</span></article>
    <DataTransferCard isAdmin={isAdmin} refresh={refresh}/>
    {isAdmin?<AIProfilesAdmin/>:<article className="card settings-card"><div className="card-head"><div><h2>{t('settings.aiUserTitle')}</h2><p>{t('settings.aiUserSub')}</p></div><ShieldCheck size={20}/></div><div className="settings-hint"><Sparkles size={16}/><span>{t('settings.aiUserHint')}</span></div></article>}
  </div></>
}
